bsc-learned() { m="$1"; shift 2>/dev/null; r=""; c=""; while [ "$#" -gt 0 ]; do case "$1" in --rule) r="${2:-}"; shift 2 2>/dev/null || shift ;; --cause) c="${2:-}"; shift 2 2>/dev/null || shift ;; *) shift ;; esac; done; if [ -z "$m" ] && [ -z "$r" ]; then echo 'bsc-learned: usage: bsc-learned "<mistake>" --rule "<rule>" [--cause "<why>"]' >&2; return 2; fi; p="pane ${BSC_AUDIT_PANE:-?}"; [ -n "${BSC_REPO_ROOT:-}" ] && p="$p, repo ${BSC_REPO_ROOT}"; bsc plan lesson add "$m" --rule "$r" --cause "$c" --from "$p"; }
